contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint256 preBalance = address(c).balance;

        bool reverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 postBalance = address(c).balance;

        // The contract exposes no getter for `intitalized`, so we drive it ourselves: `SetLogFile` can only
        // succeed before `Initialized()` is called.  Thus if it succeeded, the contract was not initialized;
        // if it reverted, it was initialized.  The rule asserts this equivalence and that no Ether moved.
        assert((reverted == false && postBalance == preBalance) || reverted == true);
    }

    receive() external payable {}
}

